insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (26, 'draft', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃに <u>遅れます</u>。', '["おくれます","まにあいます","さがします","みます"]'::jsonb, 0, '遅れます dibaca “おくれます” dan berarti terlambat.', 'Bab 26–30 · Mondai 1 No.1', 'kanji:遅れます'),
  (26, 'draft', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パーティーに <u>参加します</u>。', '["さんかします","もうしこみます","れんらくします","かたづきます"]'::jsonb, 0, '参加します dibaca “さんかします” dan berarti ikut serta.', 'Bab 26–30 · Mondai 1 No.2', 'kanji:参加します'),
  (26, 'draft', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>気分</u>が わるいです。', '["きぶん","つごう","ばしょ","こんど"]'::jsonb, 0, '気分 dibaca “きぶん” dan berarti perasaan/kondisi badan.', 'Bab 26–30 · Mondai 1 No.3', 'kanji:気分'),
  (26, 'draft', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'とりの <u>声</u>が きこえます。', '["こえ","なみ","かたち","ゆめ"]'::jsonb, 0, '声 dibaca “こえ” dan berarti suara.', 'Bab 26–30 · Mondai 1 No.4', 'kanji:声'),
  (26, 'draft', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'いぬを <u>飼います</u>。', '["かいます","たてます","はしります","とびます"]'::jsonb, 0, '飼います dibaca “かいます” dan berarti memelihara (binatang).', 'Bab 26–30 · Mondai 1 No.5', 'kanji:飼います'),
  (26, 'draft', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>将来</u>の ゆめは いしゃです。', '["しょうらい","じぶん","むかし","どうぐ"]'::jsonb, 0, '将来 dibaca “しょうらい” dan berarti masa depan.', 'Bab 26–30 · Mondai 1 No.6', 'kanji:将来'),
  (26, 'draft', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この ほんは よく <u>売れます</u>。', '["うれます","おどります","えらびます","かよいます"]'::jsonb, 0, '売れます dibaca “うれます” dan berarti terjual.', 'Bab 26–30 · Mondai 1 No.7', 'kanji:売れます'),
  (26, 'draft', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいは とても <u>優しい</u>です。', '["やさしい","えらい","ねっしんな","まじめな"]'::jsonb, 0, '優しい dibaca “やさしい” dan berarti lemah lembut/baik hati.', 'Bab 26–30 · Mondai 1 No.8', 'kanji:優しい'),
  (26, 'draft', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まどが <u>閉まります</u>。', '["しまります","あきます","きえます","こわれます"]'::jsonb, 0, '閉まります dibaca “しまります” dan berarti tertutup.', 'Bab 26–30 · Mondai 1 No.9', 'kanji:閉まります'),
  (26, 'draft', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'コップが <u>割れます</u>。', '["われます","おれます","やぶれます","よごれます"]'::jsonb, 0, '割れます dibaca “われます” dan berarti pecah.', 'Bab 26–30 · Mondai 1 No.10', 'kanji:割れます'),
  (26, 'draft', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パーティーに <u>もうしこみます</u>。', '["申し込みます","参加します","連絡します","片付きます"]'::jsonb, 0, 'もうしこみます ditulis 申し込みます, berarti mendaftar.', 'Bab 26–30 · Mondai 2 No.11', 'kanji:申し込みます'),
  (26, 'draft', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にわで <u>うんどうかい</u>を します。', '["運動会","新聞社","場所","宇宙船"]'::jsonb, 0, 'うんどうかい ditulis 運動会, berarti pesta olahraga.', 'Bab 26–30 · Mondai 2 No.12', 'kanji:運動会'),
  (26, 'draft', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'つくえの うえに <u>ほんだな</u>が あります。', '["本棚","道具","漫画","夢"]'::jsonb, 0, 'ほんだな ditulis 本棚, berarti lemari buku.', 'Bab 26–30 · Mondai 2 No.13', 'kanji:本棚'),
  (26, 'draft', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもは <u>まんが</u>が すきです。', '["漫画","道具","本棚","声"]'::jsonb, 0, 'まんが ditulis 漫画, berarti komik.', 'Bab 26–30 · Mondai 2 No.14', 'kanji:漫画'),
  (26, 'draft', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この かしゅは とても <u>にんき</u>です。', '["人気","経験","給料","会話"]'::jsonb, 0, 'にんき ditulis 人気, berarti populer.', 'Bab 26–30 · Mondai 2 No.15', 'kanji:人気'),
  (26, 'draft', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんきが <u>きえました</u>。', '["消えました","壊れました","汚れました","閉まりました"]'::jsonb, 0, 'きえました ditulis 消えました, berarti padam/mati.', 'Bab 26–30 · Mondai 2 No.16', 'kanji:消えます'),
  (26, 'draft', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>さいふ</u>を おとしました。', '["財布","袋","枝","壁"]'::jsonb, 0, 'さいふ ditulis 財布, berarti dompet.', 'Bab 26–30 · Mondai 2 No.17', 'kanji:財布'),
  (26, 'draft', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'つくえを <u>かたづけます</u>。', '["片づけます","並べます","飾ります","植えます"]'::jsonb, 0, 'かたづけます ditulis 片づけます, berarti membereskan.', 'Bab 26–30 · Mondai 2 No.18', 'kanji:片づけます'),
  (26, 'draft', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はなを <u>かざります</u>。', '["飾ります","並べます","植えます","戻します"]'::jsonb, 0, 'かざります ditulis 飾ります, berarti menghias.', 'Bab 26–30 · Mondai 2 No.19', 'kanji:飾ります'),
  (26, 'draft', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちに <u>そうだんします</u>。', '["相談します","連絡します","予習します","復習します"]'::jsonb, 0, 'そうだんします ditulis 相談します, berarti berunding/membicarakan.', 'Bab 26–30 · Mondai 2 No.20', 'kanji:相談します'),
  (26, 'draft', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>はなせます。</span><span class="arrange-chip"><b>③</b>にほんご</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>わたし</span></div><small>Petunjuk arti: “Saya bisa berbicara bahasa Jepang.”</small>', '["⑤→④→③→①→②","④→⑤→③→①→②","⑤→③→④→①→②","⑤→④→①→③→②"]'::jsonb, 0, 'Urutan yang benar: ⑤わたし→④は→③にほんご→①が→②はなせます。 が menandai objek dari kata kerja bentuk potensial seperti はなせます (Pel.27).', 'Bab 26–30 · Mondai 3 No.21', 'materi:book2:1:0'),
  (26, 'draft', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>みせ</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>で</span><span class="arrange-chip"><b>④</b>この</span><span class="arrange-chip"><b>⑤</b>カード</span><span class="arrange-chip"><b>⑥</b>つかえます。</span></div><small>Petunjuk arti: “Kartu dapat digunakan di toko ini.”</small>', '["④→①→③→⑤→②→⑥","①→④→③→⑤→②→⑥","④→③→①→⑤→②→⑥","④→①→⑤→③→②→⑥"]'::jsonb, 0, 'Urutan yang benar: ④この→①みせ→③で→⑤カード→②が→⑥つかえます。 が menandai objek kemampuan/potensial, di sini bersama つかえます (Pel.27).', 'Bab 26–30 · Mondai 3 No.22', 'materi:book2:1:0'),
  (26, 'draft', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>みえます。</span><span class="arrange-chip"><b>③</b>まど</span><span class="arrange-chip"><b>④</b>うみ</span><span class="arrange-chip"><b>⑤</b>から</span></div><small>Petunjuk arti: “Dari jendela terlihat laut.”</small>', '["③→⑤→④→①→②","⑤→③→④→①→②","③→④→⑤→①→②","③→⑤→①→④→②"]'::jsonb, 0, 'Urutan yang benar: ③まど→⑤から→④うみ→①が→②みえます。 が menandai subjek yang terlihat secara alami bersama みえます (Pel.27).', 'Bab 26–30 · Mondai 3 No.23', 'materi:book2:1:0'),
  (26, 'draft', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ホテル</span><span class="arrange-chip"><b>②</b>まえ</span><span class="arrange-chip"><b>③</b>できました。</span><span class="arrange-chip"><b>④</b>あたらしい</span><span class="arrange-chip"><b>⑤</b>えき</span><span class="arrange-chip"><b>⑥</b>に</span><span class="arrange-chip"><b>⑦</b>の</span><span class="arrange-chip"><b>⑧</b>が</span></div><small>Petunjuk arti: “Hotel baru telah dibangun di depan stasiun.”</small>', '["⑤→⑦→②→⑥→④→①→⑧→③","⑦→⑤→②→⑥→④→①→⑧→③","⑤→②→⑦→⑥→④→①→⑧→③","⑤→⑦→⑥→②→④→①→⑧→③"]'::jsonb, 0, 'Urutan yang benar: ⑤えき→⑦の→②まえ→⑥に→④あたらしい→①ホテル→⑧が→③できました。 に menandai tempat munculnya sesuatu yang baru selesai/tersedia bersama できました (Pel.27).', 'Bab 26–30 · Mondai 3 No.24', 'materi:book2:1:0'),
  (26, 'draft', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>べんきょうします。</span><span class="arrange-chip"><b>②</b>おんがく</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>ききながら</span></div><small>Petunjuk arti: “Saya belajar sambil mendengarkan musik.”</small>', '["②→③→④→①","③→②→④→①","②→④→③→①","②→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②おんがく→③を→④ききながら→①べんきょうします。 を menandai objek dari kegiatan latar (ききながら) yang dilakukan bersamaan dengan kegiatan utama (Pel.28).', 'Bab 26–30 · Mondai 3 No.25', 'materi:book2:2:0'),
  (26, 'draft', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>べんりだ</span><span class="arrange-chip"><b>②</b>まち</span><span class="arrange-chip"><b>③</b>この</span><span class="arrange-chip"><b>④</b>しずかです。</span><span class="arrange-chip"><b>⑤</b>は</span><span class="arrange-chip"><b>⑥</b>し</span></div><small>Petunjuk arti: “Kota ini praktis, dan tenang.”</small>', '["③→②→⑤→①→⑥→④","②→③→⑤→①→⑥→④","③→⑤→②→①→⑥→④","③→②→①→⑤→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ③この→②まち→⑤は→①べんりだ→⑥し→④しずかです。 し dipakai untuk menyebutkan beberapa sifat/alasan secara berturut-turut (Pel.28).', 'Bab 26–30 · Mondai 3 No.26', 'materi:book2:2:0'),
  (26, 'draft', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>しまっています。</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>まど</span><span class="arrange-chip"><b>⑤</b>きょうしつ</span></div><small>Petunjuk arti: “Jendela ruang kelas tertutup.”</small>', '["⑤→①→④→③→②","①→⑤→④→③→②","⑤→④→①→③→②","⑤→①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑤きょうしつ→①の→④まど→③が→②しまっています。 が menandai subjek dalam kalimat keadaan hasil (自動詞＋ています) (Pel.29).', 'Bab 26–30 · Mondai 3 No.27', 'materi:book2:3:0'),
  (26, 'draft', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わすれて</span><span class="arrange-chip"><b>②</b>しゅくだい</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>しまいました。</span></div><small>Petunjuk arti: “Saya terlanjur lupa PR (dengan menyesal).”</small>', '["②→③→①→④","③→②→①→④","②→①→③→④","②→③→④→①"]'::jsonb, 0, 'Urutan yang benar: ②しゅくだい→③を→①わすれて→④しまいました。 を menandai objek sebelum Kata Kerja bentuk てしまいます yang menyatakan penyesalan (Pel.29).', 'Bab 26–30 · Mondai 3 No.28', 'materi:book2:3:0'),
  (26, 'draft', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>メモ</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>うえ</span><span class="arrange-chip"><b>⑥</b>おいてあります。</span><span class="arrange-chip"><b>⑦</b>つくえ</span></div><small>Petunjuk arti: “Catatan diletakkan di atas meja.”</small>', '["⑦→②→⑤→④→①→③→⑥","②→⑦→⑤→④→①→③→⑥","⑦→⑤→②→④→①→③→⑥","⑦→②→④→⑤→①→③→⑥"]'::jsonb, 0, 'Urutan yang benar: ⑦つくえ→②の→⑤うえ→④に→①メモ→③が→⑥おいてあります。 に menandai tempat dalam kalimat keadaan hasil tindakan sengaja (他動詞＋てあります) (Pel.30).', 'Bab 26–30 · Mondai 3 No.29', 'materi:book2:4:0'),
  (26, 'draft', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でも</span><span class="arrange-chip"><b>②</b>ちょっと</span><span class="arrange-chip"><b>③</b>のみませんか。</span><span class="arrange-chip"><b>④</b>コーヒー</span></div><small>Petunjuk arti: “Bagaimana kalau minum kopi atau semacamnya?”</small>', '["②→④→①→③","④→②→①→③","②→①→④→③","②→④→③→①"]'::jsonb, 0, 'Urutan yang benar: ②ちょっと→④コーヒー→①でも→③のみませんか。 でも dipakai untuk memberi contoh/saran tanpa membatasi pilihan (Pel.30).', 'Bab 26–30 · Mondai 3 No.30', 'materi:book2:4:0'),
  (26, 'draft', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>やすんだんですか。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>どうして</span><span class="arrange-chip"><b>④</b>がっこう</span></div><small>Petunjuk arti: “Mengapa tidak masuk sekolah?”</small>', '["③→④→②→①","④→③→②→①","③→②→④→①","③→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ③どうして→④がっこう→②を→①やすんだんですか。 んですか dipakai untuk meminta penjelasan alasan atau latar belakang (Pel.26).', 'Bab 26–30 · Mondai 4 No.31', 'materi:book2:0:0'),
  (26, 'draft', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かんじ</span><span class="arrange-chip"><b>②</b>よんで</span><span class="arrange-chip"><b>③</b>この</span><span class="arrange-chip"><b>④</b>いただけませんか。</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Bisakah Anda berkenan membacakan kanji ini?”</small>', '["③→①→⑤→②→④","①→③→⑤→②→④","③→⑤→①→②→④","③→①→②→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ③この→①かんじ→⑤を→②よんで→④いただけませんか。 Kata Kerja bentuk ていただけませんか adalah cara sangat sopan untuk meminta bantuan (Pel.26).', 'Bab 26–30 · Mondai 4 No.32', 'materi:book2:0:0'),
  (26, 'draft', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きこえます。</span><span class="arrange-chip"><b>②</b>おんがく</span><span class="arrange-chip"><b>③</b>となり</span><span class="arrange-chip"><b>④</b>から</span><span class="arrange-chip"><b>⑤</b>へや</span><span class="arrange-chip"><b>⑥</b>が</span><span class="arrange-chip"><b>⑦</b>の</span></div><small>Petunjuk arti: “Dari kamar sebelah terdengar musik.”</small>', '["③→⑦→⑤→④→②→⑥→①","⑦→③→⑤→④→②→⑥→①","③→⑤→⑦→④→②→⑥→①","③→⑦→④→⑤→②→⑥→①"]'::jsonb, 0, 'Urutan yang benar: ③となり→⑦の→⑤へや→④から→②おんがく→⑥が→①きこえます。 きこえます menyatakan sesuatu terdengar secara alami, subjeknya ditandai が (Pel.27).', 'Bab 26–30 · Mondai 4 No.33', 'materi:book2:1:0'),
  (26, 'draft', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>それで</span><span class="arrange-chip"><b>③</b>いきませんでした。</span><span class="arrange-chip"><b>④</b>きのう</span><span class="arrange-chip"><b>⑤</b>は</span><span class="arrange-chip"><b>⑥</b>わたし</span><span class="arrange-chip"><b>⑦</b>あめでした。</span></div><small>Petunjuk arti: “Kemarin hujan. Karena itu, saya tidak pergi.”</small>', '["④→①→⑦→②→⑥→⑤→③","①→④→⑦→②→⑥→⑤→③","④→⑦→①→②→⑥→⑤→③","④→①→②→⑦→⑥→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ④きのう→①は→⑦あめでした。→②それで→⑥わたし→⑤は→③いきませんでした。 それで menghubungkan sebab dan akibat yang logis antara dua kalimat (Pel.28).', 'Bab 26–30 · Mondai 4 No.34', 'materi:book2:2:0'),
  (26, 'draft', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>に</span><span class="arrange-chip"><b>②</b>きっぷ</span><span class="arrange-chip"><b>③</b>の</span><span class="arrange-chip"><b>④</b>まえ</span><span class="arrange-chip"><b>⑤</b>りょこう</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>かっておきます。</span></div><small>Petunjuk arti: “Sebelum perjalanan, saya membeli tiket terlebih dahulu.”</small>', '["⑤→③→④→①→②→⑥→⑦","③→⑤→④→①→②→⑥→⑦","⑤→④→③→①→②→⑥→⑦","⑤→③→①→④→②→⑥→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑤りょこう→③の→④まえ→①に→②きっぷ→⑥を→⑦かっておきます。 Kata Kerja bentuk ておきます menyatakan persiapan yang dilakukan sebelum suatu kejadian (Pel.30).', 'Bab 26–30 · Mondai 4 No.35', 'materi:book2:4:0'),
  (26, 'draft', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'どうして　がっこうを　やすんだんですか。……びょうきだったんです。ねつが　あったら、どう　したら　いいですか。……びょういんへ　いった　ほうが　いいです。<br><small>がっこうを　やすんだ　りゆうは　なんですか。</small>', '["びょういんへ いったから","びょうきだったから","ねつが あったらいいから","びょういんへ いった ほうが いいから"]'::jsonb, 1, 'んです digunakan untuk MENJELASKAN ALASAN（「びょうきだったんです」= karena sakit）, berbeda dari たらいいですか yang MEMINTA SARAN, bukan alasan (Pel.26).', 'Bab 26–30 · Soal Cerita No.36', 'materi:book2:0:0'),
  (26, 'draft', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　へやから　うみが　みえます。となりの　へやからは、おんがくが　きこえます。えきの　まえに、あたらしい　ホテルが　できました。<br><small>あたらしく　できたのは　なんですか。</small>', '["うみ","おんがく","ホテル","へや"]'::jsonb, 2, 'できます di sini berarti “baru selesai dibangun/tersedia” (hotel baru), berbeda dari みえます (terlihat secara alami = laut) dan きこえます (terdengar secara alami = musik) (Pel.27).', 'Bab 26–30 · Soal Cerita No.37', 'materi:book2:1:0'),
  (26, 'draft', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　まいあさ　おんがくを　ききながら　べんきょうします。この　まちは　べんりだし、しずかです。<br><small>おんがくを　きくのと　べんきょうするのは、どんな　かんけいですか。</small>', '["べつべつの じかんに します","どちらも りゆうです","どうじに します","おんがくの あとで べんきょうします"]'::jsonb, 2, 'ながら menyatakan DUA kegiatan dilakukan BERSAMAAN (どうじに), berbeda dari し yang menyebutkan beberapa ALASAN/SIFAT secara berturut-turut, bukan menyatakan aksi bersamaan (Pel.28).', 'Bab 26–30 · Soal Cerita No.38', 'materi:book2:2:0'),
  (26, 'draft', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きょうしつの　まどが　しまっています。わたしは、たいせつな　しゅくだいを　わすれてしまいました。<br><small>「わすれてしまいました」から　わかる　きもちは　なんですか。</small>', '["うれしい きもち","ざんねんな きもち","あんしんした きもち","たのしい きもち"]'::jsonb, 1, 'てしまいます menunjukkan PENYESALAN atas suatu kejadian (lupa PR = ざんねん), berbeda dari ています yang hanya menyatakan KEADAAN objektif tanpa emosi (jendela tertutup) (Pel.29).', 'Bab 26–30 · Soal Cerita No.39', 'materi:book2:3:0'),
  (26, 'draft', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'つくえの　うえに　メモが　おいてあります。りょこうの　まえに、きっぷを　かっておきます。<br><small>「かっておきます」は、いつの　ための　じゅんびですか。</small>', '["いまの ため","りょこうの ため","つくえの ため","メモの ため"]'::jsonb, 1, 'ておきます menyatakan tindakan PERSIAPAN untuk kejadian di MASA DEPAN (membeli tiket sebelum perjalanan), berbeda dari てあります yang menyatakan KEADAAN HASIL dari tindakan yang sudah dilakukan dengan tujuan tertentu (catatan sudah diletakkan) (Pel.30).', 'Bab 26–30 · Soal Cerita No.40', 'materi:book2:4:0');
insert into public.quiz_questions (bab_range, status, position, category, instruction, html, options, answer, explanation, material, srs_id) values
  (26, 'published', 0, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんしゃに <u>遅れます</u>。', '["おくれます","まにあいます","さがします","みます"]'::jsonb, 0, '遅れます dibaca “おくれます” dan berarti terlambat.', 'Bab 26–30 · Mondai 1 No.1', 'kanji:遅れます'),
  (26, 'published', 1, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パーティーに <u>参加します</u>。', '["さんかします","もうしこみます","れんらくします","かたづきます"]'::jsonb, 0, '参加します dibaca “さんかします” dan berarti ikut serta.', 'Bab 26–30 · Mondai 1 No.2', 'kanji:参加します'),
  (26, 'published', 2, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>気分</u>が わるいです。', '["きぶん","つごう","ばしょ","こんど"]'::jsonb, 0, '気分 dibaca “きぶん” dan berarti perasaan/kondisi badan.', 'Bab 26–30 · Mondai 1 No.3', 'kanji:気分'),
  (26, 'published', 3, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'とりの <u>声</u>が きこえます。', '["こえ","なみ","かたち","ゆめ"]'::jsonb, 0, '声 dibaca “こえ” dan berarti suara.', 'Bab 26–30 · Mondai 1 No.4', 'kanji:声'),
  (26, 'published', 4, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'いぬを <u>飼います</u>。', '["かいます","たてます","はしります","とびます"]'::jsonb, 0, '飼います dibaca “かいます” dan berarti memelihara (binatang).', 'Bab 26–30 · Mondai 1 No.5', 'kanji:飼います'),
  (26, 'published', 5, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>将来</u>の ゆめは いしゃです。', '["しょうらい","じぶん","むかし","どうぐ"]'::jsonb, 0, '将来 dibaca “しょうらい” dan berarti masa depan.', 'Bab 26–30 · Mondai 1 No.6', 'kanji:将来'),
  (26, 'published', 6, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この ほんは よく <u>売れます</u>。', '["うれます","おどります","えらびます","かよいます"]'::jsonb, 0, '売れます dibaca “うれます” dan berarti terjual.', 'Bab 26–30 · Mondai 1 No.7', 'kanji:売れます'),
  (26, 'published', 7, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'せんせいは とても <u>優しい</u>です。', '["やさしい","えらい","ねっしんな","まじめな"]'::jsonb, 0, '優しい dibaca “やさしい” dan berarti lemah lembut/baik hati.', 'Bab 26–30 · Mondai 1 No.8', 'kanji:優しい'),
  (26, 'published', 8, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'まどが <u>閉まります</u>。', '["しまります","あきます","きえます","こわれます"]'::jsonb, 0, '閉まります dibaca “しまります” dan berarti tertutup.', 'Bab 26–30 · Mondai 1 No.9', 'kanji:閉まります'),
  (26, 'published', 9, 'Cara Baca Kanji', '＿＿＿の ことばは ひらがなで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'コップが <u>割れます</u>。', '["われます","おれます","やぶれます","よごれます"]'::jsonb, 0, '割れます dibaca “われます” dan berarti pecah.', 'Bab 26–30 · Mondai 1 No.10', 'kanji:割れます'),
  (26, 'published', 10, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'パーティーに <u>もうしこみます</u>。', '["申し込みます","参加します","連絡します","片付きます"]'::jsonb, 0, 'もうしこみます ditulis 申し込みます, berarti mendaftar.', 'Bab 26–30 · Mondai 2 No.11', 'kanji:申し込みます'),
  (26, 'published', 11, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'にわで <u>うんどうかい</u>を します。', '["運動会","新聞社","場所","宇宙船"]'::jsonb, 0, 'うんどうかい ditulis 運動会, berarti pesta olahraga.', 'Bab 26–30 · Mondai 2 No.12', 'kanji:運動会'),
  (26, 'published', 12, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'つくえの うえに <u>ほんだな</u>が あります。', '["本棚","道具","漫画","夢"]'::jsonb, 0, 'ほんだな ditulis 本棚, berarti lemari buku.', 'Bab 26–30 · Mondai 2 No.13', 'kanji:本棚'),
  (26, 'published', 13, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'こどもは <u>まんが</u>が すきです。', '["漫画","道具","本棚","声"]'::jsonb, 0, 'まんが ditulis 漫画, berarti komik.', 'Bab 26–30 · Mondai 2 No.14', 'kanji:漫画'),
  (26, 'published', 14, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'この かしゅは とても <u>にんき</u>です。', '["人気","経験","給料","会話"]'::jsonb, 0, 'にんき ditulis 人気, berarti populer.', 'Bab 26–30 · Mondai 2 No.15', 'kanji:人気'),
  (26, 'published', 15, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'でんきが <u>きえました</u>。', '["消えました","壊れました","汚れました","閉まりました"]'::jsonb, 0, 'きえました ditulis 消えました, berarti padam/mati.', 'Bab 26–30 · Mondai 2 No.16', 'kanji:消えます'),
  (26, 'published', 16, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', '<u>さいふ</u>を おとしました。', '["財布","袋","枝","壁"]'::jsonb, 0, 'さいふ ditulis 財布, berarti dompet.', 'Bab 26–30 · Mondai 2 No.17', 'kanji:財布'),
  (26, 'published', 17, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'つくえを <u>かたづけます</u>。', '["片づけます","並べます","飾ります","植えます"]'::jsonb, 0, 'かたづけます ditulis 片づけます, berarti membereskan.', 'Bab 26–30 · Mondai 2 No.18', 'kanji:片づけます'),
  (26, 'published', 18, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'はなを <u>かざります</u>。', '["飾ります","並べます","植えます","戻します"]'::jsonb, 0, 'かざります ditulis 飾ります, berarti menghias.', 'Bab 26–30 · Mondai 2 No.19', 'kanji:飾ります'),
  (26, 'published', 19, 'Penulisan Kanji', '＿＿＿の ことばは かんじで どう かきますか。1・2・3・4から いちばん いい ものを ひとつ えらんでください。', 'ともだちに <u>そうだんします</u>。', '["相談します","連絡します","予習します","復習します"]'::jsonb, 0, 'そうだんします ditulis 相談します, berarti berunding/membicarakan.', 'Bab 26–30 · Mondai 2 No.20', 'kanji:相談します'),
  (26, 'published', 20, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>はなせます。</span><span class="arrange-chip"><b>③</b>にほんご</span><span class="arrange-chip"><b>④</b>は</span><span class="arrange-chip"><b>⑤</b>わたし</span></div><small>Petunjuk arti: “Saya bisa berbicara bahasa Jepang.”</small>', '["⑤→④→③→①→②","④→⑤→③→①→②","⑤→③→④→①→②","⑤→④→①→③→②"]'::jsonb, 0, 'Urutan yang benar: ⑤わたし→④は→③にほんご→①が→②はなせます。 が menandai objek dari kata kerja bentuk potensial seperti はなせます (Pel.27).', 'Bab 26–30 · Mondai 3 No.21', 'materi:book2:1:0'),
  (26, 'published', 21, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>みせ</span><span class="arrange-chip"><b>②</b>が</span><span class="arrange-chip"><b>③</b>で</span><span class="arrange-chip"><b>④</b>この</span><span class="arrange-chip"><b>⑤</b>カード</span><span class="arrange-chip"><b>⑥</b>つかえます。</span></div><small>Petunjuk arti: “Kartu dapat digunakan di toko ini.”</small>', '["④→①→③→⑤→②→⑥","①→④→③→⑤→②→⑥","④→③→①→⑤→②→⑥","④→①→⑤→③→②→⑥"]'::jsonb, 0, 'Urutan yang benar: ④この→①みせ→③で→⑤カード→②が→⑥つかえます。 が menandai objek kemampuan/potensial, di sini bersama つかえます (Pel.27).', 'Bab 26–30 · Mondai 3 No.22', 'materi:book2:1:0'),
  (26, 'published', 22, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>が</span><span class="arrange-chip"><b>②</b>みえます。</span><span class="arrange-chip"><b>③</b>まど</span><span class="arrange-chip"><b>④</b>うみ</span><span class="arrange-chip"><b>⑤</b>から</span></div><small>Petunjuk arti: “Dari jendela terlihat laut.”</small>', '["③→⑤→④→①→②","⑤→③→④→①→②","③→④→⑤→①→②","③→⑤→①→④→②"]'::jsonb, 0, 'Urutan yang benar: ③まど→⑤から→④うみ→①が→②みえます。 が menandai subjek yang terlihat secara alami bersama みえます (Pel.27).', 'Bab 26–30 · Mondai 3 No.23', 'materi:book2:1:0'),
  (26, 'published', 23, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>ホテル</span><span class="arrange-chip"><b>②</b>まえ</span><span class="arrange-chip"><b>③</b>できました。</span><span class="arrange-chip"><b>④</b>あたらしい</span><span class="arrange-chip"><b>⑤</b>えき</span><span class="arrange-chip"><b>⑥</b>に</span><span class="arrange-chip"><b>⑦</b>の</span><span class="arrange-chip"><b>⑧</b>が</span></div><small>Petunjuk arti: “Hotel baru telah dibangun di depan stasiun.”</small>', '["⑤→⑦→②→⑥→④→①→⑧→③","⑦→⑤→②→⑥→④→①→⑧→③","⑤→②→⑦→⑥→④→①→⑧→③","⑤→⑦→⑥→②→④→①→⑧→③"]'::jsonb, 0, 'Urutan yang benar: ⑤えき→⑦の→②まえ→⑥に→④あたらしい→①ホテル→⑧が→③できました。 に menandai tempat munculnya sesuatu yang baru selesai/tersedia bersama できました (Pel.27).', 'Bab 26–30 · Mondai 3 No.24', 'materi:book2:1:0'),
  (26, 'published', 24, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>べんきょうします。</span><span class="arrange-chip"><b>②</b>おんがく</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>ききながら</span></div><small>Petunjuk arti: “Saya belajar sambil mendengarkan musik.”</small>', '["②→③→④→①","③→②→④→①","②→④→③→①","②→③→①→④"]'::jsonb, 0, 'Urutan yang benar: ②おんがく→③を→④ききながら→①べんきょうします。 を menandai objek dari kegiatan latar (ききながら) yang dilakukan bersamaan dengan kegiatan utama (Pel.28).', 'Bab 26–30 · Mondai 3 No.25', 'materi:book2:2:0'),
  (26, 'published', 25, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>べんりだ</span><span class="arrange-chip"><b>②</b>まち</span><span class="arrange-chip"><b>③</b>この</span><span class="arrange-chip"><b>④</b>しずかです。</span><span class="arrange-chip"><b>⑤</b>は</span><span class="arrange-chip"><b>⑥</b>し</span></div><small>Petunjuk arti: “Kota ini praktis, dan tenang.”</small>', '["③→②→⑤→①→⑥→④","②→③→⑤→①→⑥→④","③→⑤→②→①→⑥→④","③→②→①→⑤→⑥→④"]'::jsonb, 0, 'Urutan yang benar: ③この→②まち→⑤は→①べんりだ→⑥し→④しずかです。 し dipakai untuk menyebutkan beberapa sifat/alasan secara berturut-turut (Pel.28).', 'Bab 26–30 · Mondai 3 No.26', 'materi:book2:2:0'),
  (26, 'published', 26, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>の</span><span class="arrange-chip"><b>②</b>しまっています。</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>まど</span><span class="arrange-chip"><b>⑤</b>きょうしつ</span></div><small>Petunjuk arti: “Jendela ruang kelas tertutup.”</small>', '["⑤→①→④→③→②","①→⑤→④→③→②","⑤→④→①→③→②","⑤→①→③→④→②"]'::jsonb, 0, 'Urutan yang benar: ⑤きょうしつ→①の→④まど→③が→②しまっています。 が menandai subjek dalam kalimat keadaan hasil (自動詞＋ています) (Pel.29).', 'Bab 26–30 · Mondai 3 No.27', 'materi:book2:3:0'),
  (26, 'published', 27, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>わすれて</span><span class="arrange-chip"><b>②</b>しゅくだい</span><span class="arrange-chip"><b>③</b>を</span><span class="arrange-chip"><b>④</b>しまいました。</span></div><small>Petunjuk arti: “Saya terlanjur lupa PR (dengan menyesal).”</small>', '["②→③→①→④","③→②→①→④","②→①→③→④","②→③→④→①"]'::jsonb, 0, 'Urutan yang benar: ②しゅくだい→③を→①わすれて→④しまいました。 を menandai objek sebelum Kata Kerja bentuk てしまいます yang menyatakan penyesalan (Pel.29).', 'Bab 26–30 · Mondai 3 No.28', 'materi:book2:3:0'),
  (26, 'published', 28, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>メモ</span><span class="arrange-chip"><b>②</b>の</span><span class="arrange-chip"><b>③</b>が</span><span class="arrange-chip"><b>④</b>に</span><span class="arrange-chip"><b>⑤</b>うえ</span><span class="arrange-chip"><b>⑥</b>おいてあります。</span><span class="arrange-chip"><b>⑦</b>つくえ</span></div><small>Petunjuk arti: “Catatan diletakkan di atas meja.”</small>', '["⑦→②→⑤→④→①→③→⑥","②→⑦→⑤→④→①→③→⑥","⑦→⑤→②→④→①→③→⑥","⑦→②→④→⑤→①→③→⑥"]'::jsonb, 0, 'Urutan yang benar: ⑦つくえ→②の→⑤うえ→④に→①メモ→③が→⑥おいてあります。 に menandai tempat dalam kalimat keadaan hasil tindakan sengaja (他動詞＋てあります) (Pel.30).', 'Bab 26–30 · Mondai 3 No.29', 'materi:book2:4:0'),
  (26, 'published', 29, 'Partikel', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>でも</span><span class="arrange-chip"><b>②</b>ちょっと</span><span class="arrange-chip"><b>③</b>のみませんか。</span><span class="arrange-chip"><b>④</b>コーヒー</span></div><small>Petunjuk arti: “Bagaimana kalau minum kopi atau semacamnya?”</small>', '["②→④→①→③","④→②→①→③","②→①→④→③","②→④→③→①"]'::jsonb, 0, 'Urutan yang benar: ②ちょっと→④コーヒー→①でも→③のみませんか。 でも dipakai untuk memberi contoh/saran tanpa membatasi pilihan (Pel.30).', 'Bab 26–30 · Mondai 3 No.30', 'materi:book2:4:0'),
  (26, 'published', 30, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>やすんだんですか。</span><span class="arrange-chip"><b>②</b>を</span><span class="arrange-chip"><b>③</b>どうして</span><span class="arrange-chip"><b>④</b>がっこう</span></div><small>Petunjuk arti: “Mengapa tidak masuk sekolah?”</small>', '["③→④→②→①","④→③→②→①","③→②→④→①","③→④→①→②"]'::jsonb, 0, 'Urutan yang benar: ③どうして→④がっこう→②を→①やすんだんですか。 んですか dipakai untuk meminta penjelasan alasan atau latar belakang (Pel.26).', 'Bab 26–30 · Mondai 4 No.31', 'materi:book2:0:0'),
  (26, 'published', 31, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>かんじ</span><span class="arrange-chip"><b>②</b>よんで</span><span class="arrange-chip"><b>③</b>この</span><span class="arrange-chip"><b>④</b>いただけませんか。</span><span class="arrange-chip"><b>⑤</b>を</span></div><small>Petunjuk arti: “Bisakah Anda berkenan membacakan kanji ini?”</small>', '["③→①→⑤→②→④","①→③→⑤→②→④","③→⑤→①→②→④","③→①→②→⑤→④"]'::jsonb, 0, 'Urutan yang benar: ③この→①かんじ→⑤を→②よんで→④いただけませんか。 Kata Kerja bentuk ていただけませんか adalah cara sangat sopan untuk meminta bantuan (Pel.26).', 'Bab 26–30 · Mondai 4 No.32', 'materi:book2:0:0'),
  (26, 'published', 32, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>きこえます。</span><span class="arrange-chip"><b>②</b>おんがく</span><span class="arrange-chip"><b>③</b>となり</span><span class="arrange-chip"><b>④</b>から</span><span class="arrange-chip"><b>⑤</b>へや</span><span class="arrange-chip"><b>⑥</b>が</span><span class="arrange-chip"><b>⑦</b>の</span></div><small>Petunjuk arti: “Dari kamar sebelah terdengar musik.”</small>', '["③→⑦→⑤→④→②→⑥→①","⑦→③→⑤→④→②→⑥→①","③→⑤→⑦→④→②→⑥→①","③→⑦→④→⑤→②→⑥→①"]'::jsonb, 0, 'Urutan yang benar: ③となり→⑦の→⑤へや→④から→②おんがく→⑥が→①きこえます。 きこえます menyatakan sesuatu terdengar secara alami, subjeknya ditandai が (Pel.27).', 'Bab 26–30 · Mondai 4 No.33', 'materi:book2:1:0'),
  (26, 'published', 33, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>は</span><span class="arrange-chip"><b>②</b>それで</span><span class="arrange-chip"><b>③</b>いきませんでした。</span><span class="arrange-chip"><b>④</b>きのう</span><span class="arrange-chip"><b>⑤</b>は</span><span class="arrange-chip"><b>⑥</b>わたし</span><span class="arrange-chip"><b>⑦</b>あめでした。</span></div><small>Petunjuk arti: “Kemarin hujan. Karena itu, saya tidak pergi.”</small>', '["④→①→⑦→②→⑥→⑤→③","①→④→⑦→②→⑥→⑤→③","④→⑦→①→②→⑥→⑤→③","④→①→②→⑦→⑥→⑤→③"]'::jsonb, 0, 'Urutan yang benar: ④きのう→①は→⑦あめでした。→②それで→⑥わたし→⑤は→③いきませんでした。 それで menghubungkan sebab dan akibat yang logis antara dua kalimat (Pel.28).', 'Bab 26–30 · Mondai 4 No.34', 'materi:book2:2:0'),
  (26, 'published', 34, 'Susunan Kalimat', 'Susun potongan kata berikut, lalu pilih urutan nomor yang benar.', '<div class="arrange-chips"><span class="arrange-chip"><b>①</b>に</span><span class="arrange-chip"><b>②</b>きっぷ</span><span class="arrange-chip"><b>③</b>の</span><span class="arrange-chip"><b>④</b>まえ</span><span class="arrange-chip"><b>⑤</b>りょこう</span><span class="arrange-chip"><b>⑥</b>を</span><span class="arrange-chip"><b>⑦</b>かっておきます。</span></div><small>Petunjuk arti: “Sebelum perjalanan, saya membeli tiket terlebih dahulu.”</small>', '["⑤→③→④→①→②→⑥→⑦","③→⑤→④→①→②→⑥→⑦","⑤→④→③→①→②→⑥→⑦","⑤→③→①→④→②→⑥→⑦"]'::jsonb, 0, 'Urutan yang benar: ⑤りょこう→③の→④まえ→①に→②きっぷ→⑥を→⑦かっておきます。 Kata Kerja bentuk ておきます menyatakan persiapan yang dilakukan sebelum suatu kejadian (Pel.30).', 'Bab 26–30 · Mondai 4 No.35', 'materi:book2:4:0'),
  (26, 'published', 35, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'どうして　がっこうを　やすんだんですか。……びょうきだったんです。ねつが　あったら、どう　したら　いいですか。……びょういんへ　いった　ほうが　いいです。<br><small>がっこうを　やすんだ　りゆうは　なんですか。</small>', '["びょういんへ いったから","びょうきだったから","ねつが あったらいいから","びょういんへ いった ほうが いいから"]'::jsonb, 1, 'んです digunakan untuk MENJELASKAN ALASAN（「びょうきだったんです」= karena sakit）, berbeda dari たらいいですか yang MEMINTA SARAN, bukan alasan (Pel.26).', 'Bab 26–30 · Soal Cerita No.36', 'materi:book2:0:0'),
  (26, 'published', 36, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしの　へやから　うみが　みえます。となりの　へやからは、おんがくが　きこえます。えきの　まえに、あたらしい　ホテルが　できました。<br><small>あたらしく　できたのは　なんですか。</small>', '["うみ","おんがく","ホテル","へや"]'::jsonb, 2, 'できます di sini berarti “baru selesai dibangun/tersedia” (hotel baru), berbeda dari みえます (terlihat secara alami = laut) dan きこえます (terdengar secara alami = musik) (Pel.27).', 'Bab 26–30 · Soal Cerita No.37', 'materi:book2:1:0'),
  (26, 'published', 37, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'わたしは　まいあさ　おんがくを　ききながら　べんきょうします。この　まちは　べんりだし、しずかです。<br><small>おんがくを　きくのと　べんきょうするのは、どんな　かんけいですか。</small>', '["べつべつの じかんに します","どちらも りゆうです","どうじに します","おんがくの あとで べんきょうします"]'::jsonb, 2, 'ながら menyatakan DUA kegiatan dilakukan BERSAMAAN (どうじに), berbeda dari し yang menyebutkan beberapa ALASAN/SIFAT secara berturut-turut, bukan menyatakan aksi bersamaan (Pel.28).', 'Bab 26–30 · Soal Cerita No.38', 'materi:book2:2:0'),
  (26, 'published', 38, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'きょうしつの　まどが　しまっています。わたしは、たいせつな　しゅくだいを　わすれてしまいました。<br><small>「わすれてしまいました」から　わかる　きもちは　なんですか。</small>', '["うれしい きもち","ざんねんな きもち","あんしんした きもち","たのしい きもち"]'::jsonb, 1, 'てしまいます menunjukkan PENYESALAN atas suatu kejadian (lupa PR = ざんねん), berbeda dari ています yang hanya menyatakan KEADAAN objektif tanpa emosi (jendela tertutup) (Pel.29).', 'Bab 26–30 · Soal Cerita No.39', 'materi:book2:3:0'),
  (26, 'published', 39, 'Soal Cerita', 'Baca cerita pendek berikut, lalu jawab pertanyaannya.', 'つくえの　うえに　メモが　おいてあります。りょこうの　まえに、きっぷを　かっておきます。<br><small>「かっておきます」は、いつの　ための　じゅんびですか。</small>', '["いまの ため","りょこうの ため","つくえの ため","メモの ため"]'::jsonb, 1, 'ておきます menyatakan tindakan PERSIAPAN untuk kejadian di MASA DEPAN (membeli tiket sebelum perjalanan), berbeda dari てあります yang menyatakan KEADAAN HASIL dari tindakan yang sudah dilakukan dengan tujuan tertentu (catatan sudah diletakkan) (Pel.30).', 'Bab 26–30 · Soal Cerita No.40', 'materi:book2:4:0');
